entries.syntax_block:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
while (Line <> Undefined) {        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
}
Reader.Close();

entries.syntax_block_ves:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
While Line <> Undefined Do        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
EndDo;
Reader.Close();

entries.example:
Reader = New TextReader("C:\in\sales.csv", TextEncoding.UTF8);
Line = Reader.ReadLine();
while (Line <> Undefined) {              // Undefined, а не "": порожній рядок — це рядок
    if (Line <> "") {
        Cut = Find(Line, ";");
        Code = Left(Line, Cut - 1);      // перше поле
    }
    Line = Reader.ReadLine();
}
Reader.Close();

Reader = New TextReader(first);
Message(Reader.ReadLine());
Reader.Open(second);          // перший файл відпущено; читач стоїть на рядку 1 другого
Message(Reader.ReadLine());
Reader.Close();

Line = Reader.ReadLine();
while (Line <> Undefined) {       // а не while (Line <> "")
    Message(Line);
    Line = Reader.ReadLine();
}

Header = Reader.ReadLine();       // перший рядок окремо
Body = Reader.Read();             // усе, що після нього, разом із переведеннями рядків
Reader.Close();

Reader = New TextReader(path);
for (n = 1 To Reader.LineCount()) {
    Message(Reader.GetLine(n));
}
Reader.Close();

Reader = New TextReader(path);
Message(Reader.GetLine(1));                    // рядок заголовка
Message(Reader.GetLine(Reader.LineCount()));   // останній
Message(Reader.ReadLine());                    // так само рядок 1: GetLine його не зсунув
Reader.Close();

entries.syntax_block:
Writer = New TextWriter(path, TextEncoding.UTF8);
Writer = New TextWriter(path, TextEncoding.UTF8, True);   // append instead of replace

Writer.WriteLine("code;name;qty");
Writer.Write("00001;Paper;12");
Writer.Close();                                           // here, and only here, a failure is told

entries.example:
Writer = New TextWriter(GetTempDir() + "sales.csv", TextEncoding.UTF8);
Writer.WriteLine("code;name;qty");
Writer.WriteLine("00001;Папір;12");
Writer.Close();                      // вивантаження ціле лише після того, як це повернулося

Writer = New TextWriter(first);
Writer.WriteLine("one");
Writer.Open(second);          // перший файл ЗАКРИВАЄТЬСЯ тут — і про невдале закриття скажуть тут
Writer.WriteLine("two");
Writer.Close();

Writer.Write("00001;");
Writer.Write("Папір;");
Writer.WriteLine("12");        // переведення рядка, що завершує рядок файлу

try {
    Writer.Close();
} except {
    Message("вивантаження не дійшло до диска: " + ErrorDescription());
}

